import { z } from "zod";
import { unitIdSchema } from "../admissions";

const uuidSchema = z.string().uuid();

export const googlePhotoSyncRequestPayloadSchema = z
  .object({
    syncId: uuidSchema.optional(),
    limit: z.number().int().positive().max(10_000).optional(),
    batchSize: z.number().int().min(1).max(200).optional(),
    maxPhotosPerUniversity: z.number().int().min(1).max(50).optional(),
    skipIfHasAtLeast: z.number().int().min(0).max(50).optional(),
    includeUnitIds: z.array(unitIdSchema).min(1).optional(),
    dryRun: z.boolean().optional(),
  })
  .strict();

export const googlePhotoSyncBatchRequestPayloadSchema = z
  .object({
    syncId: uuidSchema,
    batchIndex: z.number().int().min(0),
    totalBatches: z.number().int().min(1),
    universityUnitIds: z.array(unitIdSchema).min(1),
    maxPhotosPerUniversity: z.number().int().min(1).max(50),
    skipIfHasAtLeast: z.number().int().min(0).max(50),
  })
  .strict();

export const googlePhotoSyncBatchCompletedPayloadSchema = z
  .object({
    syncId: uuidSchema,
    batchIndex: z.number().int().min(0),
    totalBatches: z.number().int().min(1),
    results: z.array(
      z
        .object({
          unitid: unitIdSchema,
          status: z.enum(["skipped", "succeeded", "failed"]),
          uploaded: z.number().int().min(0).optional(),
          duplicates: z.number().int().min(0).optional(),
          existingBefore: z.number().int().min(0).optional(),
          existingAfter: z.number().int().min(0).optional(),
          message: z.string().optional(),
          error: z.string().optional(),
        })
        .strict(),
    ),
  })
  .strict();

export const googlePhotoSyncCompletedPayloadSchema = z
  .object({
    syncId: uuidSchema,
    batchesProcessed: z.number().int().min(0),
    universitiesProcessed: z.number().int().min(0),
    universitiesSkipped: z.number().int().min(0),
    universitiesFailed: z.number().int().min(0),
    totalPhotosUploaded: z.number().int().min(0),
  })
  .strict();

export type GooglePhotoSyncRequestPayload = z.infer<
  typeof googlePhotoSyncRequestPayloadSchema
>;
export type GooglePhotoSyncBatchRequestPayload = z.infer<
  typeof googlePhotoSyncBatchRequestPayloadSchema
>;
export type GooglePhotoSyncBatchCompletedPayload = z.infer<
  typeof googlePhotoSyncBatchCompletedPayloadSchema
>;
export type GooglePhotoSyncCompletedPayload = z.infer<
  typeof googlePhotoSyncCompletedPayloadSchema
>;

